-- MHT partner migration: rename placeholders, set commissions, add missing, deactivate archived
-- Target business: MHT Show Ops (5a16bfc4-3363-43e1-bd8c-30afcf3d3529)
begin;

-- 1. keep a rollback snapshot
create table if not exists show_suppliers_backup_20260815 as
  select * from public.show_suppliers where business_id='5a16bfc4-3363-43e1-bd8c-30afcf3d3529';

-- 2. add legacy id column so this is re-runnable and traceable
alter table public.show_suppliers add column if not exists legacy_tourop_id integer;

-- 3. stamp legacy ids onto the existing 'Partner #N' placeholders
update public.show_suppliers set legacy_tourop_id = (substring(name from 10))::int
 where business_id='5a16bfc4-3363-43e1-bd8c-30afcf3d3529' and name ~ '^Partner #[0-9]+$';

-- 4. rename placeholders to real names + set commission/billing (booking links preserved)
update public.show_suppliers s set
  name = v.name, partner_type = v.ptype, billing_mode = v.bmode,
  deposit_percent = v.pct, active = v.act, notes = v.notes, updated_at = now()
